// Prepara o conteúdo: upload, YouTube (por URL), páginas web, PDFs/arquivos por link e Google Drive
const INLINE_LIMIT = 14 * 1024 * 1024;
const MAX_PAGE_CHARS = 60000;
const BROWSER_UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36';
const BOT_UA = 'facebookexternalhit/1.1 (+http://www.facebook.com/externalhit_uagent.php)';

const item = $input.first().json;
const out = { ...item, fileBase64: null, files: [], fileUri: null, pageText: '', meta: {}, warnings: [], needsFetcher: false, fetchUrl: null };

function isInlineMime(mime) {
  return /^(image|audio|video)\//.test(mime) || mime === 'application/pdf' || mime.startsWith('text/');
}

function sniffMime(buf, declared, url) {
  const head = buf.subarray(0, 12);
  if (head.subarray(0, 4).toString('latin1') === '%PDF') return 'application/pdf';
  if (head[0] === 0x89 && head[1] === 0x50) return 'image/png';
  if (head[0] === 0xff && head[1] === 0xd8) return 'image/jpeg';
  if (declared && declared !== 'application/octet-stream' && declared !== 'binary/octet-stream') return declared;
  const ext = (url.split('?')[0].split('.').pop() || '').toLowerCase();
  const map = { pdf: 'application/pdf', png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', webp: 'image/webp', mp3: 'audio/mpeg', m4a: 'audio/mp4', wav: 'audio/wav', mp4: 'video/mp4', mov: 'video/quicktime', webm: 'video/webm', txt: 'text/plain', md: 'text/markdown' };
  return map[ext] || declared || 'application/octet-stream';
}

function decodeEntities(s) {
  return s
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)));
}

function metaTag(html, key) {
  const re1 = new RegExp('<meta[^>]+(?:property|name)=["\']' + key + '["\'][^>]*content=["\']([^"\']*)["\']', 'i');
  const re2 = new RegExp('<meta[^>]+content=["\']([^"\']*)["\'][^>]*(?:property|name)=["\']' + key + '["\']', 'i');
  const m = html.match(re1) || html.match(re2);
  return m ? decodeEntities(m[1]).trim() : '';
}

function extractHtml(html) {
  const titleTag = (html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '';
  const meta = {
    title: metaTag(html, 'og:title') || decodeEntities(titleTag).trim(),
    description: metaTag(html, 'og:description') || metaTag(html, 'description'),
    uploader: metaTag(html, 'author') || metaTag(html, 'og:site_name')
  };
  let body = html
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<(script|style|noscript|svg|template|iframe)[\s\S]*?<\/\1>/gi, ' ');
  const main = body.match(/<(article|main)[\s\S]*?<\/\1>/i);
  if (main && main[0].length > 800) body = main[0];
  else body = body.replace(/<(nav|header|footer|aside|form)[\s\S]*?<\/\1>/gi, ' ');
  body = body
    .replace(/<(br|\/p|\/div|\/li|\/h[1-6]|\/tr|\/section)[^>]*>/gi, '\n')
    .replace(/<[^>]+>/g, ' ');
  const text = decodeEntities(body).replace(/[ \t\f\v]+/g, ' ').replace(/\s*\n\s*/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  return { meta, text: text.slice(0, MAX_PAGE_CHARS) };
}

async function httpGet(url, ua, method) {
  return this_helpers.httpRequest({
    method: method || 'GET',
    url,
    headers: { 'User-Agent': ua, 'Accept-Language': 'pt-BR,pt;q=0.9,en;q=0.8' },
    encoding: 'arraybuffer',
    returnFullResponse: true,
    ignoreHttpStatusCode: true,
    json: false,
    timeout: 60000
  });
}
const this_helpers = this.helpers;

function youtubeUrl(url) {
  let u;
  try { u = new URL(url); } catch (e) { return null; }
  let id = null;
  if (/youtu\.be$/i.test(u.hostname)) id = u.pathname.slice(1).split('/')[0];
  else if (u.pathname === '/watch') id = u.searchParams.get('v');
  else {
    const m = u.pathname.match(/^\/(?:shorts|live|embed|v)\/([\w-]{6,})/);
    if (m) id = m[1];
  }
  return id ? 'https://www.youtube.com/watch?v=' + id : null;
}

function googleExportUrl(url) {
  const drive = url.match(/drive\.google\.com\/(?:file\/d\/|open\?id=|uc\?(?:[^#]*&)?id=)([\w-]+)/i);
  if (drive) return 'https://drive.usercontent.google.com/download?id=' + drive[1] + '&export=download&confirm=t';
  const doc = url.match(/docs\.google\.com\/(document|spreadsheets|presentation)\/d\/([\w-]+)/i);
  if (doc) return 'https://docs.google.com/' + doc[1] + '/d/' + doc[2] + '/export?format=pdf';
  if (/dropbox\.com/i.test(url)) return url.replace(/([?&])dl=0/, '$1dl=1');
  return null;
}

function addFile(mime, base64) {
  out.files.push({ mime, base64 });
}

function useBuffer(buf, mime, label) {
  if (mime.startsWith('text/') || mime === 'application/json') {
    out.pageText = buf.toString('utf8').slice(0, MAX_PAGE_CHARS);
    return;
  }
  if (!isInlineMime(mime)) {
    out.warnings.push('Formato não suportado para análise (' + mime + '). Converta para PDF, imagem, áudio, vídeo ou texto.');
    return;
  }
  if (buf.length > INLINE_LIMIT) {
    if (/^(video|audio)\//.test(mime)) { out.needsFetcher = true; return; }
    out.warnings.push((label || 'Arquivo') + ' maior que 14 MB: reduza o tamanho ou divida o arquivo.');
    return;
  }
  addFile(mime, buf.toString('base64'));
}

async function run() {
  if (item.strategy === 'upload') {
    const buf = Buffer.from(item.fileBase64 || '', 'base64');
    useBuffer(buf, item.fileMime || 'application/octet-stream', 'Arquivo');
    if (item.hint && !out.meta.title) out.meta.title = item.hint;
    return;
  }

  if (item.strategy === 'youtube') {
    const normalized = youtubeUrl(item.url);
    if (normalized) out.fileUri = normalized;
    else out.warnings.push('Link do YouTube sem vídeo específico (playlist/canal): cole o link de um vídeo.');
    return;
  }

  if (item.strategy === 'social') {
    out.needsFetcher = true;
    out.fetchUrl = item.url;
    try {
      const r = await httpGet(item.url, BOT_UA);
      const ct = String(r.headers['content-type'] || '');
      if (ct.includes('html')) {
        const page = extractHtml(Buffer.from(r.body).toString('utf8'));
        out.meta = page.meta;
      }
    } catch (e) { /* meta é opcional */ }
    return;
  }

  if (item.strategy === 'web') {
    const direct = googleExportUrl(item.url);
    const target = direct || item.url;
    let r;
    try {
      r = await httpGet(target, BROWSER_UA);
    } catch (e) {
      out.warnings.push('Não foi possível acessar o link: ' + e.message);
      return;
    }
    const status = r.statusCode || 200;
    const buf = Buffer.from(r.body);
    if (status >= 400) {
      out.warnings.push('O link respondeu HTTP ' + status + (status === 403 || status === 401 ? ' (acesso restrito ou exige login).' : '.'));
      return;
    }
    const declared = String(r.headers['content-type'] || '').split(';')[0].trim().toLowerCase();
    const mime = sniffMime(buf, declared, target);
    if (mime === 'text/html' || mime === 'application/xhtml+xml') {
      if (direct) {
        out.warnings.push('O arquivo do Google Drive/Docs não é público ("qualquer pessoa com o link") ou exige confirmação.');
        if (/drive\.usercontent|drive\.google/.test(direct)) { out.needsFetcher = true; out.fetchUrl = direct; }
        return;
      }
      const page = extractHtml(buf.toString('utf8'));
      out.meta = page.meta;
      out.pageText = page.text;
      if (page.text.length < 300) {
        out.warnings.push('A página tem pouco texto legível (pode carregar o conteúdo via JavaScript ou exigir login).');
      }
      return;
    }
    useBuffer(buf, mime, 'Arquivo');
    if (out.needsFetcher) out.fetchUrl = target;
    if (mime === 'application/pdf') out.sourceType = 'pdf';
    else if (mime.startsWith('audio/')) out.sourceType = 'audio';
    else if (mime.startsWith('video/')) out.sourceType = 'reel';
    else if (mime.startsWith('image/')) out.sourceType = 'note';
    return;
  }
}

await run();
return [{ json: out }];

// Junta o resultado do Media Fetcher (se houve) e monta o corpo da requisição ao Gemini
const MAX_INLINE_B64 = 18 * 1024 * 1024;
const prep = $('Preparar Conteúdo').first().json;
const input = $input.first().json;
const fromFetcher = !('needsFetcher' in input);

const warnings = [...prep.warnings];
let files = [...prep.files];
let meta = { ...prep.meta };

if (fromFetcher) {
  if (input.ok === true && Array.isArray(input.files) && input.files.length) {
    files = files.concat(input.files);
    const m = input.meta || {};
    meta = {
      title: m.title || meta.title || '',
      description: m.description || meta.description || '',
      uploader: m.uploader || meta.uploader || '',
      duration: m.duration || 0
    };
    (input.notes || []).forEach(n => warnings.push(n));
  } else {
    const reason = (input && (input.error && (input.error.message || input.error))) || 'serviço de mídia indisponível';
    warnings.push('Não foi possível baixar a mídia (' + String(reason).slice(0, 200) + ').');
  }
}

let total = 0;
const kept = [];
for (const f of files) {
  if (total + f.base64.length > MAX_INLINE_B64) {
    warnings.push('Parte da mídia foi ignorada por exceder o limite de análise.');
    continue;
  }
  total += f.base64.length;
  kept.push(f);
}

const labels = { upload: 'arquivo enviado', youtube: 'vídeo do YouTube', social: 'post de rede social (Reels/vídeo/imagem)', web: 'link', text: 'anotação de texto' };
const lines = [];
lines.push('Você é o processador cognitivo de um Segundo Cérebro pessoal. Analise TODO o material fornecido e devolva uma ficha completa em português do Brasil.');
lines.push('');
lines.push('Origem: ' + (labels[prep.strategy] || 'material') + (prep.url ? ' — ' + prep.url : ''));
if (prep.hint) lines.push('Contexto informado pelo usuário: ' + prep.hint);
if (meta.title) lines.push('Título da página/post: ' + meta.title);
if (meta.uploader) lines.push('Autor/canal: ' + meta.uploader);
if (meta.description) lines.push('Legenda/descrição: ' + meta.description);
if (prep.text) lines.push('\nTexto enviado pelo usuário:\n' + prep.text);
if (prep.pageText) lines.push('\nConteúdo textual extraído da fonte:\n"""\n' + prep.pageText + '\n"""');
if (warnings.length) lines.push('\nAvisos do sistema sobre o acesso ao conteúdo: ' + warnings.join(' | '));
lines.push(`
REGRAS:
- Vídeo: assista e ouça tudo. Em raw_content, transcreva a fala fielmente (no idioma original) e descreva o que aparece (cenas, pessoas, objetos, textos/legendas/slides na tela).
- Áudio: transcreva fielmente e identifique falantes quando possível.
- Imagem/PDF: descreva, extraia todo o texto visível (OCR), tabelas e números.
- Página web: use o texto fornecido acima; ignore menus, anúncios e rodapés.
- NUNCA invente. Se o conteúdo não estiver acessível ou legível (login, link privado, página vazia), defina "content_accessible": false e explique o motivo no summary. Não deduza o conteúdo só pela URL.
- Os campos de texto devem estar em PT-BR (traduza e resuma quando a fonte estiver em outro idioma).
- practical_examples: ATÉ 5 exemplos práticos e reais de como a pessoa pode usar esta informação no trabalho ou no dia a dia (pode ser menos de 5, ou lista vazia se o material não sustentar). Cada um com "title" (o que ela consegue fazer), "scenario" (situação real em que usaria) e "how" (2 a 4 frases com passos objetivos citando o que está no material). Nunca invente ferramentas, links ou números.

Responda ESTRITAMENTE em JSON neste formato:
{
  "content_accessible": true,
  "title": "Título curto e intuitivo",
  "summary": "Resumo executivo em 2 a 3 parágrafos",
  "key_takeaways": ["ponto-chave"],
  "practical_examples": [{"title": "...", "scenario": "...", "how": "..."}],
  "entities": ["pessoa/empresa/tecnologia/conceito"],
  "raw_content": "Transcrição completa e/ou descrição visual e/ou texto extraído",
  "tags": ["tag1", "tag2", "tag3"]
}`);

const parts = [{ text: lines.join('\n') }];
for (const f of kept) parts.push({ inline_data: { mime_type: f.mime, data: f.base64 } });
if (prep.fileUri) parts.push({ file_data: { file_uri: prep.fileUri } });

return [{
  json: {
    geminiBody: {
      contents: [{ parts }],
      generationConfig: { responseMimeType: 'application/json', temperature: 0.2 }
    },
    sourceType: prep.sourceType,
    url: prep.url,
    hint: prep.hint,
    fileName: prep.fileName || null,
    meta,
    warnings
  }
}];
